function rectTile(x,y,w,h,label,color){return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="5" fill="${color}" fill-opacity=".15" stroke="${color}" stroke-width="2"/>${`<text x="${x+5}" y="${y+h/2+4}" fill="${color}" font-size="10" font-weight="700">${label}</text>`}`;}
function whyFor(q){
 const t=(q.topic||'').toLowerCase();
 if(/વાડ|પરિમિતિ/.test(t))return 'અહીં કિનારીની કુલ લંબાઈ જોઈએ છે, અંદરનું ક્ષેત્રફળ નહીં.';
 if(/રસ્તો/.test(t))return 'રસ્તો = મોટો ભાગ − રસ્તા વગરનો અંદરનો ભાગ; અંદરના માપમાં બંને બાજુની પહોળાઈ ઘટે છે.';
 if(/હેરોન/.test(t))return 'ઊંચાઈ આપવામાં નથી; ત્રણેય બાજુથી ક્ષેત્રફળ મેળવવા Heronનું સૂત્ર યોગ્ય છે.';
 if(/સમબાજુ ત્રિકોણ/.test(t))return 'સમબાજુ ત્રિકોણમાં ત્રણેય બાજુ સમાન હોવાથી સીધા ક્ષેત્રફળ અને ઊંચાઈનાં સૂત્ર વાપરી શકાય.';
 if(/આટા|રોલર/.test(t))return 'દરેક સંપૂર્ણ ચક્કરમાં કાપેલું અંતર પૈડાં/રોલરના પરિઘ જેટલું હોય છે.';
 if(/અર્ધવર્તુળ/.test(t))return 'બંધ પરિમિતિમાં વક્ર ચાપ ઉપરાંત સીધો વ્યાસ પણ ગણવો પડે છે.';
 if(/સમલંબ/.test(t))return 'સમલંબ ચતુષ્કોણનું ક્ષેત્રફળ સમાંતર બાજુઓની સરેરાશ × તેમની વચ્ચેનું લંબ અંતર છે.';
 if(/rhombus|ચતુષ્કોણ/.test(t))return 'વિકર્ણો કાટખૂણે દુભાગે છે; અડધા વિકર્ણોથી બનેલા સમકોણ ત્રિકોણનો ઉપયોગ કરો.';
 if(/ઘન|સમઘન/.test(t))return 'TSAમાં છ સમાન ચોરસ સપાટી હોય છે; પહેલા બાજુ શોધો, પછી ઘનફળ અને વિકર્ણ.';
 if(/લંબઘન|સળિયા/.test(t))return 'રૂમની અંદરનો સૌથી મોટો સળિયો અવકાશ વિકર્ણ છે; ત્રણેય પરિમાણો જરૂરી છે.';
 if(/ટાંકી|પ્રવાહ|પાઈપ|લીટર/.test(t))return 'પ્રવાહ દર = પાઈપનું cross-section × ઝડપ; સમય = ટાંકીનું ઘનફળ ÷ પ્રવાહ દર.';
 if(/શંકુ/.test(t))return 'શંકુમાં ઊંચાઈ અને ત્રિજ્યા પરથી તિર્યક ઊંચાઈ કાઢો; ખુલ્લા તંબુ માટે ફક્ત curved surface લો.';
 if(/ગોલક|અર્ધગોલક/.test(t))return 'પ્રશ્નમાં curved કે total surface પૂછ્યું છે તે પ્રમાણે આધાર સપાટી ઉમેરવી કે નહીં તે નક્કી કરો.';
 if(/recasting|ઓગાળ|તાર/.test(t))return 'આકાર બદલાય છે, પદાર્થનું ઘનફળ નહીં; જૂનું ઘનફળ નવી વસ્તુઓના કુલ ઘનફળ સમાન રાખો.';
 if(/ટકાવારી|વધારો/.test(t))return 'લંબાઈમાં ફેરફારનો ગુણક લો; ક્ષેત્રફળ માટે તેનો વર્ગ અને ઘનફળ માટે ઘન કરો.';
 if(/જમીન|વીઘા|ગુંઠા|વાર|એકર/.test(t))return 'આ પ્રશ્ન સૂત્રનો નહીં, યોગ્ય પ્રદેશ અને એકમ-રૂપાંતરણનો છે; conversion chain બનાવો.';
 if(/ટાઇલ/.test(t))return 'એકમ સરખા કર્યા પછી કુલ ફ્લોર વિસ્તારને એક ટાઇલના વિસ્તારથી ભાગો.';
 if(/frustum|ડોલ|આડછેદ/.test(t))return 'Frustumમાં ઉપર-નીચેના બે અલગ radius છે; બંનેને volume formulaમાં સામેલ કરો.';
 return 'આપેલા માપને ઓળખી યોગ્ય 2D/3D quantity પસંદ કરો અને એકમો ચકાસો.';
}
function solution(q){
 const n=Number(q.question_number)||1,exp=String(q.explanation||'').trim(),lines=exp.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
 const steps=lines.map((s,i)=>`<div class="men-step"><span class="men-step-no">${String(i+1).padStart(2,'0')}</span><div><small>${i===0?'GIVEN / MODEL':i===lines.length-1?'RESULT / CHECK':'CALCULATION'}</small><p>${esc(s)}</p></div></div>`).join('');
 const keys=Object.keys(q.options||{}),answer=String(q.correct_answer||'').toUpperCase(),ans=q.options?.[answer]||'જવાબ ઉપલબ્ધ નથી';
 const opts=keys.map(k=>`<span class="men-option ${k===answer?'correct':''}"><b>${k}</b>${esc(q.options[k])}</span>`).join('');
 return `<article data-mensuration-q="${n}" class="men-solution men-q${n}" style="--men-accent:${C(n)}"><header class="men-solution-head"><div><span class="men-eyebrow">MENSURATION FIELD NOTES · Q${String(n).padStart(2,'0')}</span><h3>${esc(q.topic)}</h3><p>આ પ્રશ્નમાં કઈ ગણિતીય વસ્તુ શોધવાની છે અને કઈ રીત લાગુ પડે છે.</p></div><div class="men-q-index">${String(n).padStart(2,'0')}<small>/50</small></div></header><div class="men-question"><span>QUESTION</span><p>${esc(q.question_text)}</p></div>${scene(n,q).replace('class="men-scene','class="men-scene men-scene-q'+n)}<div class="men-insight"><b>આ રીત કેમ?</b><p>${esc(whyFor(q))}</p></div><div class="men-solution-body"><div class="men-flow-title"><span>WORKED LOGIC</span><h4>એક પગલું → એક કારણ → આગળની ગણતરી</h4></div>${steps||'<p>Source explanation ઉપલબ્ધ નથી.</p>'}</div><div class="men-answer"><div><small>ANSWER KEY</small><strong>${esc(answer)} · ${esc(ans)}</strong><p>મૂળ JSONમાં આપેલા answer key પ્રમાણે.</p></div><div class="men-options">${opts}</div></div><footer class="men-footer"><span>TOPIC · ${esc(q.topic)}</span><span>UNIT CHECK · ${esc((exp.match(/ચોરસ મીટર|ચો\\.મી|ચોરસ સેમી|ઘન સેમી|લીટર|મીટર|સેમી|વાર|ગુંઠા/g)||[]).slice(-1)[0]||'અંતિમ એકમ ચકાસો')}</span></footer></article>`;
}
function installStyles(){
 if(document.getElementById('mensuration-design-style'))return;
 const s=document.createElement('style');s.id='mensuration-design-style';s.textContent=`
.men-solution{--men-accent:#38bdf8;background:linear-gradient(145deg,#101b2d,#0c1423 72%);color:#e5edf8;border:1px solid #26374d;border-radius:20px;overflow:hidden;margin:14px 0;font-family:inherit;box-shadow:0 18px 45px #02061735}
.men-solution-head{display:flex;justify-content:space-between;gap:16px;padding:22px 24px 16px;background:radial-gradient(ellipse at 90% 0%,color-mix(in srgb,var(--men-accent) 20%,transparent),transparent 60%),#121f32;border-bottom:1px solid #293b52}
.men-eyebrow,.men-question>span,.men-scene .scene-label,.men-flow-title>span{font-size:10px;letter-spacing:1.7px;font-weight:800;color:var(--men-accent)}
.men-solution-head h3{font-size:19px;line-height:1.35;margin:7px 0;color:#f8fafc}.men-solution-head p{font-size:12px;color:#9fb0c5;margin:0}
.men-q-index{font-size:34px;line-height:1;font-weight:850;color:var(--men-accent);white-space:nowrap}.men-q-index small{font-size:11px;color:#8ea0b7}
.men-question{margin:18px 22px 10px;padding:14px 17px;border-left:3px solid var(--men-accent);background:#17263a;border-radius:0 12px 12px 0}.men-question p{margin:6px 0 0;line-height:1.75;font-size:14px;color:#f1f5f9}
.men-scene{margin:14px 22px;padding:16px;border:1px solid #2b405a;border-radius:16px;background:radial-gradient(ellipse at 50% 0%,#1d3049,#101a2b 75%);position:relative;overflow:hidden}.men-scene .scene-label{display:block;margin-bottom:10px;color:#a7bdd6}.men-svg{width:100%;max-height:220px;display:block}.men-svg text{font-family:inherit}.men-equation,.scene-equation{display:flex;align-items:center;justify-content:center;gap:12px;flex-wrap:wrap;margin-top:10px;padding:10px 12px;border-radius:10px;background:#0a1321;color:#b9c8da;font-size:12px}.scene-equation strong{color:var(--men-accent);font-size:17px}.scene-equation b{color:#fbbf24}
.men-insight{display:grid;grid-template-columns:105px 1fr;gap:10px;margin:12px 22px;padding:13px 15px;background:color-mix(in srgb,var(--men-accent) 10%,#111d2e);border:1px solid color-mix(in srgb,var(--men-accent) 38%,#26374d);border-radius:12px}.men-insight b{color:var(--men-accent);font-size:12px}.men-insight p{margin:0;font-size:13px;line-height:1.65;color:#d5e1ee}
.men-solution-body{padding:8px 22px 18px}.men-flow-title{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:8px 0 12px}.men-flow-title h4{font-size:14px;margin:0;color:#f8fafc}
.men-step{display:grid;grid-template-columns:38px 1fr;gap:12px;position:relative;padding:10px 12px;margin:8px 0;background:#142237;border:1px solid #263a52;border-radius:12px}.men-step:not(:last-child):after{content:"";position:absolute;left:29px;bottom:-10px;width:2px;height:10px;background:var(--men-accent);opacity:.55}.men-step-no{width:30px;height:30px;display:grid;place-items:center;border-radius:9px;background:color-mix(in srgb,var(--men-accent) 18%,#152337);color:var(--men-accent);font-size:11px;font-weight:850}.men-step small{font-size:9px;letter-spacing:1.4px;color:#8fa5bf;font-weight:800}.men-step p{margin:4px 0 0;line-height:1.75;font-size:13px;color:#e3edf8;white-space:normal}
.men-answer{display:grid;grid-template-columns:minmax(180px,.8fr) minmax(0,1.2fr);gap:14px;padding:17px 22px;background:#0a1321;border-top:1px solid #2a3b50}.men-answer small{font-size:9px;letter-spacing:1.4px;color:#8fa5bf;font-weight:800}.men-answer strong{display:block;color:#86efac;font-size:17px;margin:6px 0}.men-answer p{font-size:10px;color:#8294aa;margin:0}.men-options{display:grid;grid-template-columns:1fr 1fr;gap:6px}.men-option{display:flex;gap:7px;align-items:flex-start;padding:7px 8px;border:1px solid #2a3b50;border-radius:8px;color:#aebed0;font-size:11px}.men-option b{color:#e2e8f0}.men-option.correct{border-color:#22c55e;background:#14532d35;color:#bbf7d0}
.men-footer{display:flex;justify-content:space-between;gap:12px;padding:10px 22px;border-top:1px solid #24364b;color:#71849d;font-size:9px;letter-spacing:.7px}
@media(max-width:600px){.men-solution-head{padding:17px}.men-question,.men-scene,.men-insight{margin-left:12px;margin-right:12px}.men-solution-body{padding-left:12px;padding-right:12px}.men-answer{grid-template-columns:1fr;padding:14px}.men-flow-title{align-items:flex-start;flex-direction:column}.men-insight{grid-template-columns:1fr;gap:4px}.men-option{font-size:10px}.men-svg{max-height:180px}.men-footer{flex-direction:column}}
@media print{.men-solution{break-inside:avoid;background:white;color:#111}.men-step,.men-question,.men-scene{background:#f8fafc;color:#111}}
.men-note-visual{margin:14px 0 18px;padding:12px 14px;border:1px solid #dbe4ee;border-radius:14px;background:linear-gradient(180deg,#f8fbff,#f1f5f9);break-inside:avoid}.men-note-visual-label{font:700 12px/1.5 Inter,"Noto Sans Gujarati",sans-serif;color:#475569;margin:0 0 7px}.men-note-visual svg{display:block;width:100%;height:auto;max-height:240px}.men-note-visual text{font-family:Inter,"Noto Sans Gujarati",sans-serif}@media print{.men-note-visual{background:#fff;border-color:#cbd5e1}}
`;
 document.head.appendChild(s);
}
function addNotes(){
 NOTES.m14=NOTES.m14||[];
 NOTE_DATA.forEach(([title,body])=>{
  const entry=[title,body.split('\n')];
  const index=NOTES.m14.findIndex(x=>x&&x[0]===title);
  if(index>=0)NOTES.m14[index]=entry;else NOTES.m14.push(entry);
 });
}
function addQuestions(){
 PYQ.m14=PYQ.m14||[];
 const existing=new Set(PYQ.m14.map(q=>q&&q.mensurationKey).filter(Boolean));
 let added=0;
 DATA.questions.forEach(q=>{
  const key='mensuration:'+q.question_number;if(existing.has(key))return;
  const keys=['A','B','C','D'].filter(k=>Object.prototype.hasOwnProperty.call(q.options||{},k));
  const answer=keys.indexOf(String(q.correct_answer||'').toUpperCase());
  const item={t:'x',q:q.question_text,o:keys.map(k=>String(q.options[k])),a:answer>=0?answer:0,y:`Mensuration 2D & 3D · ${q.topic}`,e:q.explanation,h:'',mensurationKey:key,mensurationQuestionNumber:q.question_number,topic:q.topic};
  item.h=solution(q);
  PYQ.m14.push(item);added++;
 });
 console.info('[Mensuration] m14 questions:',PYQ.m14.filter(q=>q&&q.mensurationKey).length,'new:',added);
}
if(typeof V!=='undefined'){
 V.m14=V.m14||[];
 if(!V.m14.some(v=>v&&v[1]==='2dVeR_Yd0U0'))V.m14.push(['ક્ષેત્રફળ, પૃષ્ઠફળ અને ઘનફળ (Mensuration 2D & 3D) — Lecture · 48:24 થી શરૂ','2dVeR_Yd0U0',0]);
}
function installLectureStart(){
 if(typeof document==='undefined'||document.documentElement.dataset.m14LectureStart)return;
 document.documentElement.dataset.m14LectureStart='1';
 document.addEventListener('click',function(event){
  const a=event.target&&event.target.closest?event.target.closest('a.vt'):null;
  if(!a)return;
  if(a.href.indexOf('watch?v=2dVeR_Yd0U0')!==-1&&a.href.indexOf('t=2904s')===-1)a.href+='&t=2904s';
 },true);
 const labelObserver=new MutationObserver(()=>{
  document.querySelectorAll('.vd').forEach(row=>{
   const a=row.querySelector('a.vt');
   if(!a||a.href.indexOf('watch?v=2dVeR_Yd0U0')===-1)return;
   const duration=row.querySelector('span.mu.sm');
   if(duration&&duration.textContent.trim()==='0m')duration.textContent='48:24 થી શરૂ';
  });
  const summary=document.querySelector('#s-lec .sh .mu.sm');
  if(summary&&summary.textContent.includes('કુલ 0m'))summary.textContent=summary.textContent.replace('કુલ 0m','વિડિયોનો કુલ સમય ઉપલબ્ધ નથી');
 });
 labelObserver.observe(document.body,{childList:true,subtree:true});
}
